package dk.jamesbabz.madkursus.tools.recipetemplate;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import dk.jamesbabz.madkursus.service.models.*;
import java.io.IOException;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;

/** Generates an external-author-safe reference from canonical catalogs and enums only. */
public final class RecipeAuthoringReferenceGenerator {
    private static final ObjectMapper JSON=new ObjectMapper().enable(SerializationFeature.INDENT_OUTPUT);
    private final Path project;
    public RecipeAuthoringReferenceGenerator(Path project){this.project=project.toAbsolutePath().normalize();}

    public Path generate(Path output)throws IOException {
        Path productsPath=project.resolve("src/main/resources/seed/product-templates.json"),processesPath=project.resolve("src/main/resources/seed/cooking-processes.json");
        JsonNode productSource=JSON.readTree(productsPath.toFile()),processSource=JSON.readTree(processesPath.toFile());ObjectNode root=JSON.createObjectNode();
        ObjectNode metadata=root.putObject("metadata");metadata.put("format","madkursus-recipe-authoring-reference");metadata.put("version",1);metadata.put("language","da");metadata.put("deterministic",true);metadata.put("productCatalogSha256",sha256(productsPath));metadata.put("cookingProcessCatalogSha256",sha256(processesPath));metadata.put("purpose","Canonical recipe-authoring metadata only.");
        ArrayNode products=root.putArray("productTemplates");List<JsonNode> sortedProducts=new ArrayList<>();productSource.path("products").forEach(sortedProducts::add);sortedProducts.sort(Comparator.comparing(v->v.path("key").asText()));for(JsonNode source:sortedProducts){ObjectNode value=products.addObject();copy(source,value,"key","name","defaultUnit");value.set("trackingMode",source.path("defaultTrackingMode"));value.set("aliases",source.path("aliases").deepCopy());}
        ArrayNode processes=root.putArray("cookingProcesses");List<JsonNode> sortedProcesses=new ArrayList<>();processSource.path("processes").forEach(sortedProcesses::add);sortedProcesses.sort(Comparator.comparing(v->v.path("key").asText()));for(JsonNode source:sortedProcesses)processes.add(process(source));
        ArrayNode units=root.putArray("recipeUnits");for(RecipeUnit unit:RecipeUnit.values()){ObjectNode value=units.addObject();value.put("key",unit.name());value.put("dimension",dimension(unit));value.put("practicalLabel",unitLabel(unit));unit.toMilliliters(java.math.BigDecimal.ONE).ifPresent(v->value.put("millilitersPerUnit",v));}
        ArrayNode equipment=root.putArray("equipmentTypes");for(EquipmentType type:EquipmentType.values()){ObjectNode value=equipment.addObject();value.put("key",type.name());value.put("labelDa",equipmentLabel(type));}
        root.set("draftContract",contract());
        Files.createDirectories(output.toAbsolutePath().getParent());JSON.writerWithDefaultPrettyPrinter().writeValue(output.toFile(),root);return output.toAbsolutePath().normalize();
    }

    private ObjectNode process(JsonNode source){ObjectNode result=JSON.createObjectNode();copy(source,result,"key","name","description");ArrayNode required=result.putArray("requiredInputs"),optional=result.putArray("optionalInputs"),overrideable=result.putArray("overrideableValues"),derived=result.putArray("derivedValues"),defaults=result.putArray("defaultValues");for(JsonNode parameter:source.path("parameters")){String sourceKind=parameter.path("source").asText(parameter.path("default").isObject()?"DEFAULT":"INPUT");if(sourceKind.equals("INPUT")){ObjectNode input=(parameter.path("required").asBoolean()?required:optional).addObject();parameter(input,parameter);input.set("accepts",accepts(parameter.path("type").asText()));}if(sourceKind.equals("DERIVED")){ObjectNode value=derived.addObject();parameter(value,parameter);copy(parameter,value,"derivedFrom","rule","unit");value.put("overrideable",parameter.path("overrideable").asBoolean());}if(sourceKind.equals("DEFAULT")||sourceKind.equals("OVERRIDEABLE_DEFAULT")){ObjectNode value=defaults.addObject();parameter(value,parameter);value.set("default",parameter.path("default").deepCopy());value.put("overrideable",sourceKind.equals("OVERRIDEABLE_DEFAULT")||parameter.path("overrideable").asBoolean());}if(sourceKind.equals("OVERRIDEABLE_DEFAULT")||parameter.path("overrideable").asBoolean()){ObjectNode value=overrideable.addObject();parameter(value,parameter);value.put("source",sourceKind);}}
        if(source.has("equipment"))result.set("equipment",source.path("equipment").deepCopy());if(source.has("timing"))result.set("timing",source.path("timing").deepCopy());return result;}
    private void parameter(ObjectNode target,JsonNode source){copy(source,target,"key","label","type");target.put("required",source.path("required").asBoolean());}
    private ArrayNode accepts(String type){ArrayNode values=JSON.createArrayNode();switch(type){case "INGREDIENT_QUANTITY","INGREDIENT_LIST"->{values.add("ingredient");values.add("preparedComponent");}case "QUANTITY"->values.add("quantity");case "DURATION"->values.add("durationSeconds");case "TEMPERATURE"->values.add("temperatureCelsius");case "HEAT_LEVEL"->values.add("heatLevel");case "NUMBER"->values.add("number");case "TEXT"->values.add("text");default->values.add("unknown");}return values;}

    private ObjectNode contract(){ObjectNode root=JSON.createObjectNode();root.put("contract","RecipeTemplateDraft");root.put("canonicalExample","docs/examples/recipe-template-draft.json");root.putArray("requiredTopLevel").add("key").add("name").add("ingredients").add("steps");root.putArray("optionalTopLevel").add("description").add("preparation").add("preparedComponents").add("equipmentRequirements");ObjectNode shapes=root.putObject("shapes");shape(shapes,"ingredient",List.of("key","productTemplate","quantity","unit"),List.of("preparation"),"productTemplate must be a key from productTemplates; quantities are for one portion.");shape(shapes,"instruction",List.of(),List.of("plain string","{parts:[instructionPart,...]}"),"Use exactly one form. Plain strings are backward compatible and appropriate only when no recipe quantity must scale.");shape(shapes,"instructionPart",List.of("exactly one part kind"),List.of("{text:string}","{ingredient:key}","{ingredient:key,quantity:number,unit:RecipeUnit}","{component:key}","{scaledNumber:number}"),"Ingredient and scaledNumber values scale by portions; text, sizes and times remain unchanged. Component renders its name only.");shape(shapes,"preparation",List.of("instruction"),List.of("component"),"instruction may be a plain string or structured instruction; component must be a local PreparedComponent key.");shape(shapes,"preparedComponent",List.of("key","name","ingredients"),List.of("sortOrder","preparation"),"Ingredient allocations reference local ingredient keys and do not create stock requirements.");shape(shapes,"preparedComponentIngredient",List.of("ingredient","quantity","unit"),List.of(),"Allocates an existing RecipeTemplate ingredient.");shape(shapes,"textStep",List.of("type=TEXT","instruction"),List.of(),"instruction accepts the same plain/structured forms as preparation.");shape(shapes,"processStep",List.of("type=PROCESS","process","bindings"),List.of(),"process must be a key from cookingProcesses.");shape(shapes,"binding",List.of(),List.of("ingredient+quantity+unit","component","quantity+unit","durationSeconds","temperatureCelsius","heatLevel","number","text"),"Use exactly the form accepted by the selected process input/override metadata.");shape(shapes,"equipmentRequirement",List.of(),List.of("equipment type string","equipmentType","label"),"equipmentType must be a key from equipmentTypes; a custom label may be used alone.");root.putArray("rules").add("Stable local keys use UPPER_SNAKE_CASE.").add("ProductTemplate and CookingProcess keys must come from this reference and must not be invented.").add("DO NOT embed scalable Recipe ingredient quantities in plain text; use an ingredient instruction part.").add("Plain numbers are appropriate for non-scaling size/time guidance such as 2 cm or 30 seconds.").add("Place a complete CookingProcess at the correct top-level position; do not duplicate its action in an earlier TEXT step.").add("Parallel process scheduling is not represented; do not imitate it with duplicated instructions.").add("Component and direct process allocations combined may not exceed an ingredient total.").add("Passing a PreparedComponent to a process does not allocate its ingredients again.").add("Only fields listed in overrideableValues may override process-owned behavior.");return root;}
    private void shape(ObjectNode shapes,String name,List<String> required,List<String> optional,String note){ObjectNode value=shapes.putObject(name);ArrayNode r=value.putArray("required"),o=value.putArray("optionalForms");required.forEach(r::add);optional.forEach(o::add);value.put("note",note);}
    private void copy(JsonNode source,ObjectNode target,String...fields){for(String field:fields)if(source.has(field)&&!source.get(field).isNull())target.set(field,source.get(field).deepCopy());}
    private String sha256(Path path)throws IOException{try{byte[] hash=MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(path));return HexFormat.of().formatHex(hash);}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
    private String dimension(RecipeUnit unit){return switch(unit){case GRAM->"MASS";case MILLILITER,DECILITER,TEASPOON,TABLESPOON->"VOLUME";case PIECE->"COUNT";case GRINDER_TURN->"GRINDER_TURN";};}
    private String unitLabel(RecipeUnit unit){return switch(unit){case GRAM->"g";case MILLILITER->"ml";case DECILITER->"dl";case TEASPOON->"tsk";case TABLESPOON->"spsk";case PIECE->"stk";case GRINDER_TURN->"omgange";};}
    private String equipmentLabel(EquipmentType type){return switch(type){case STOVE->"Komfur";case OVEN->"Ovn";case POT->"Gryde";case PAN->"Stegepande";case AIR_FRYER->"Airfryer";case THERMOMETER->"Stegetermometer";case MICROWAVE->"Mikroovn";};}

    public static void main(String[]args)throws Exception{Path output=args.length==0?Path.of("build/recipe-authoring/recipe-authoring-reference.json"):Path.of(args[0]);System.out.println("Generated RecipeTemplate authoring reference: "+new RecipeAuthoringReferenceGenerator(Path.of(".")).generate(output));}
}
